import sys
from math import isqrt

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    rows = {}
    for i in range(n):
        x = int(data[1 + 3 * i]); y = int(data[2 + 3 * i]); r = int(data[3 + 3 * i])
        rr = r * r
        for dy in range(-r, r + 1):
            half = isqrt(rr - dy * dy)
            rows.setdefault(y + dy, []).append((x - half, x + half))
    total = 0
    for iv in rows.values():
        iv.sort()
        cur_l, cur_r = iv[0]
        for l, r_ in iv[1:]:
            if l > cur_r:
                total += cur_r - cur_l + 1
                cur_l, cur_r = l, r_
            elif r_ > cur_r:
                cur_r = r_
        total += cur_r - cur_l + 1
    print(total)

